#include <cstdint>
#include <format>
#include <iostream>

// The number of ways to climb n steps taking one or two at a time, straight from the definition:
// the last move was either one step or two, and the two cases share nothing.
[[nodiscard]] std::int64_t ways(std::int64_t n, std::int64_t& calls) {
  ++calls;
  if (n <= 1) return 1;  // one way to stand still, one way to climb a single step
  return ways(n - 1, calls) + ways(n - 2, calls);
}

int main() {
  std::cout << std::format("{:>4}{:>12}{:>14}\n", "n", "ways", "calls");
  for (const std::int64_t n : {1, 2, 5, 10, 20, 30}) {
    std::int64_t calls = 0;
    const std::int64_t answer = ways(n, calls);
    std::cout << std::format("{:>4}{:>12}{:>14}\n", n, answer, calls);
  }
}

