#include <cstddef>
#include <cstdint>
#include <format>
#include <iostream>
#include <optional>
#include <span>
#include <vector>

struct Work {
  std::int64_t answer = 0;
  std::int64_t steps = 0;  // calls made, or table cells filled
};

[[nodiscard]] std::int64_t plain(std::int64_t n, std::int64_t& calls) {
  ++calls;
  if (n <= 1) return 1;
  return plain(n - 1, calls) + plain(n - 2, calls);
}

[[nodiscard]] std::int64_t memo(std::int64_t n, std::vector<std::optional<std::int64_t>>& known,
                                std::int64_t& calls) {
  ++calls;
  if (n <= 1) return 1;
  std::optional<std::int64_t>& slot = known[static_cast<std::size_t>(n)];
  if (slot) return *slot;  // answered before, so this branch stops here
  slot = memo(n - 1, known, calls) + memo(n - 2, known, calls);
  return *slot;
}

[[nodiscard]] Work by_recursion(std::int64_t n) {
  Work w;
  w.answer = plain(n, w.steps);
  return w;
}

[[nodiscard]] Work by_memo(std::int64_t n) {
  Work w;
  std::vector<std::optional<std::int64_t>> known(static_cast<std::size_t>(n + 1), std::nullopt);
  w.answer = memo(n, known, w.steps);
  return w;
}

[[nodiscard]] Work by_table(std::int64_t n) {
  Work w;
  std::vector<std::int64_t> table(static_cast<std::size_t>(n + 1), 0);
  table[0] = 1;
  ++w.steps;
  if (n >= 1) {
    table[1] = 1;
    ++w.steps;
  }
  for (std::int64_t i = 2; i <= n; ++i) {
    table[static_cast<std::size_t>(i)] =
        table[static_cast<std::size_t>(i - 1)] + table[static_cast<std::size_t>(i - 2)];
    ++w.steps;
  }
  w.answer = table[static_cast<std::size_t>(n)];
  return w;
}

[[nodiscard]] Work by_rolling(std::int64_t n) {
  Work w;
  std::int64_t two_back = 1;  // ways(i - 2)
  std::int64_t one_back = 1;  // ways(i - 1)
  w.steps = 2;
  for (std::int64_t i = 2; i <= n; ++i) {
    const std::int64_t here = one_back + two_back;
    two_back = one_back;
    one_back = here;
    ++w.steps;
  }
  w.answer = n <= 1 ? 1 : one_back;
  return w;
}

int main() {
  std::cout << std::format("{:>4}{:>10}{:>14}{:>8}{:>8}{:>9}{:>8}\n", "n", "ways", "plain", "memo", "table",
                           "rolling", "agree");
  for (const std::int64_t n : {5, 10, 20, 30}) {
    const Work a = by_recursion(n);
    const Work b = by_memo(n);
    const Work c = by_table(n);
    const Work d = by_rolling(n);
    const bool agree = a.answer == b.answer && b.answer == c.answer && c.answer == d.answer;
    std::cout << std::format("{:>4}{:>10}{:>14}{:>8}{:>8}{:>9}{:>8}\n", n, a.answer, a.steps, b.steps, c.steps,
                             d.steps, agree);
  }
}

#include <format>
#include <iostream>

// The rolling form, correct in every way except the type of its accumulator.
[[nodiscard]] int ways(int n) {
  int two_back = 1;
  int one_back = 1;
  for (int i = 2; i <= n; ++i) {
    const int here = one_back + two_back;
    two_back = one_back;
    one_back = here;
  }
  return n <= 1 ? 1 : one_back;
}

int main() {
  std::cout << std::format("ways(45) = {}\n", ways(45)) << std::flush;  // flushed, so it survives the abort
  std::cout << std::format("ways(46) = {}\n", ways(46));
}

#include <algorithm>
#include <cstddef>
#include <cstdint>
#include <format>
#include <iostream>
#include <optional>
#include <span>
#include <string>
#include <vector>

// best[i] is the least energy needed to stand on level i. You may start on level 0 or 1 for free,
// and stepping off level j costs cost[j]. The top is the position one past the last level.
[[nodiscard]] std::vector<std::int64_t> best_table(std::span<const std::int64_t> cost) {
  const std::ptrdiff_t n = std::ssize(cost);
  std::vector<std::int64_t> best(static_cast<std::size_t>(n + 1), 0);
  for (std::ptrdiff_t i = 2; i <= n; ++i)
    best[static_cast<std::size_t>(i)] =
        std::min(best[static_cast<std::size_t>(i - 1)] + cost[static_cast<std::size_t>(i - 1)],
                 best[static_cast<std::size_t>(i - 2)] + cost[static_cast<std::size_t>(i - 2)]);
  return best;
}

// The same recurrence with two variables instead of a table.
[[nodiscard]] std::int64_t cheapest(std::span<const std::int64_t> cost) {
  std::int64_t two_back = 0;  // best[i - 2]
  std::int64_t one_back = 0;  // best[i - 1]
  for (std::ptrdiff_t i = 2; i <= std::ssize(cost); ++i) {
    const std::int64_t here = std::min(one_back + cost[static_cast<std::size_t>(i - 1)],
                                       two_back + cost[static_cast<std::size_t>(i - 2)]);
    two_back = one_back;
    one_back = here;
  }
  return std::ssize(cost) < 2 ? 0 : one_back;
}

// The same recurrence written as a recursion that remembers its answers.
[[nodiscard]] std::int64_t from_top(std::span<const std::int64_t> cost, std::ptrdiff_t i,
                                    std::vector<std::optional<std::int64_t>>& known, std::int64_t& calls) {
  ++calls;
  if (i <= 1) return 0;
  std::optional<std::int64_t>& slot = known[static_cast<std::size_t>(i)];
  if (slot) return *slot;
  slot = std::min(from_top(cost, i - 1, known, calls) + cost[static_cast<std::size_t>(i - 1)],
                  from_top(cost, i - 2, known, calls) + cost[static_cast<std::size_t>(i - 2)]);
  return *slot;
}

[[nodiscard]] std::string show(std::span<const std::int64_t> v) {
  std::string out;
  for (const std::int64_t x : v) out += std::format("{}{}", out.empty() ? "" : " ", x);
  return out.empty() ? "(none)" : out;
}

void report(std::span<const std::int64_t> cost) {
  const std::vector<std::int64_t> best = best_table(cost);
  std::vector<std::optional<std::int64_t>> known(cost.size() + 1, std::nullopt);
  std::int64_t calls = 0;
  const std::int64_t top_down = from_top(cost, std::ssize(cost), known, calls);
  std::cout << std::format("cost    {}\n", show(cost));
  std::cout << std::format("best    {}\n", show(best));
  std::cout << std::format("answer  table {}, two variables {}, memoised {} in {} calls\n", best.back(),
                           cheapest(cost), top_down, calls);
}

int main() {
  const std::vector<std::int64_t> three{10, 15, 20};
  report(three);
  const std::vector<std::int64_t> ten{1, 100, 1, 1, 1, 100, 1, 1, 100, 1};
  report(ten);
  const std::vector<std::int64_t> one{7};
  report(one);
  report({});
}

#include <algorithm>
#include <cstddef>
#include <cstdint>
#include <format>
#include <iostream>
#include <span>
#include <string>
#include <vector>

struct Plan {
  std::int64_t total = 0;
  std::vector<std::ptrdiff_t> chosen;  // indices taken, in increasing order
};

// best[i] is the most that can be taken from the first i values with no two adjacent.
[[nodiscard]] Plan best_plan(std::span<const std::int64_t> values) {
  const std::ptrdiff_t n = std::ssize(values);
  std::vector<std::int64_t> best(static_cast<std::size_t>(n + 1), 0);
  for (std::ptrdiff_t i = 1; i <= n; ++i) {
    const std::int64_t skip = best[static_cast<std::size_t>(i - 1)];
    const std::int64_t take = (i >= 2 ? best[static_cast<std::size_t>(i - 2)] : 0) +
                              values[static_cast<std::size_t>(i - 1)];
    best[static_cast<std::size_t>(i)] = std::max(skip, take);
  }
  Plan plan;
  plan.total = best[static_cast<std::size_t>(n)];
  for (std::ptrdiff_t i = n; i > 0;) {  // walk back: was value i - 1 taken?
    const std::int64_t without = best[static_cast<std::size_t>(i - 1)];
    if (best[static_cast<std::size_t>(i)] == without) {
      --i;  // the best did not need this one
    } else {
      plan.chosen.push_back(i - 1);
      i -= 2;
    }
  }
  std::ranges::reverse(plan.chosen);
  return plan;
}

// The same total with two variables and no way to say which values were taken.
[[nodiscard]] std::int64_t best_total(std::span<const std::int64_t> values) {
  std::int64_t two_back = 0;
  std::int64_t one_back = 0;
  for (const std::int64_t v : values) {
    const std::int64_t here = std::max(one_back, two_back + v);
    two_back = one_back;
    one_back = here;
  }
  return one_back;
}

[[nodiscard]] std::string show(std::span<const std::ptrdiff_t> v) {
  std::string out;
  for (const std::ptrdiff_t x : v) out += std::format("{}{}", out.empty() ? "" : " ", x);
  return out.empty() ? "(none)" : out;
}

void report(std::span<const std::int64_t> values) {
  const Plan plan = best_plan(values);
  std::string input;
  for (const std::int64_t v : values) input += std::format("{}{}", input.empty() ? "" : " ", v);
  std::cout << std::format("{:<26}{:>4}  from {:<10}  two variables {}\n",
                           input.empty() ? "(empty)" : input, plan.total, show(plan.chosen),
                           best_total(values));
}

int main() {
  report(std::vector<std::int64_t>{1, 2, 3, 1});
  report(std::vector<std::int64_t>{2, 7, 9, 3, 1});
  report(std::vector<std::int64_t>{2, 1, 1, 2});
  report(std::vector<std::int64_t>{3, 3, 3});
  report(std::vector<std::int64_t>{5});
  report({});
}
